  const downloadText = (name,text,type='text/plain') => { const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([text],{type})); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),800); };

  // ---------- Visual shell ----------
  const revealObserver = new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.08});
  $$('.reveal').forEach(el=>revealObserver.observe(el));
