  $('#themeBtn').onclick=()=>{root.classList.toggle('light');store.set('atlasiq_theme',root.classList.contains('light')?'light':'dark');drawAllCanvases();};

  function initParticles(){
    const c=$('#particleCanvas'),ctx=c.getContext('2d'); let pts=[];
    const resize=()=>{c.width=innerWidth*devicePixelRatio;c.height=innerHeight*devicePixelRatio;c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);pts=Array.from({length:Math.min(60,Math.floor(innerWidth/22))},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-.5)*.16,vy:(Math.random()-.5)*.16,r:Math.random()*1.2+.3}));};
    const tick=()=>{ctx.clearRect(0,0,innerWidth,innerHeight);ctx.fillStyle=root.classList.contains('light')?'rgba(35,45,70,.23)':'rgba(235,240,255,.22)';pts.forEach(p=>{p.x+=p.vx;p.y+=p.vy;if(p.x<0)p.x=innerWidth;if(p.x>innerWidth)p.x=0;if(p.y<0)p.y=innerHeight;if(p.y>innerHeight)p.y=0;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();});requestAnimationFrame(tick);};
    resize(); addEventListener('resize',resize); tick();
  }
  initParticles();
  $$('.tilt-card').forEach(card=>{ card.addEventListener('mousemove',e=>{ if(innerWidth<800)return; const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`rotateX(${-y*4}deg) rotateY(${x*5}deg)`;}); card.addEventListener('mouseleave',()=>card.style.transform='');});

  // ---------- Modal plumbing ----------
  $$('.modal').forEach(modal=>{ $('.modal-backdrop',modal)?.addEventListener('click',()=>closeModal(modal)); $('.modal-close',modal)?.addEventListener('click',()=>closeModal(modal)); });
  addEventListener('keydown',e=>{if(e.key==='Escape'){$$('.modal.open').forEach(closeModal);$('#amyPanel').classList.remove('open');}});

