  function renderCommands(q=''){const list=commands.filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase())).slice(0,12);$('#commandResults').innerHTML=list.map((x,i)=>`<button class="command-result ${i===0?'active':''}" data-command="${escapeHTML(x[1])}"><span>${escapeHTML(x[0])}</span><small>${escapeHTML(x[2])}</small></button>`).join('');$$('[data-command]').forEach(b=>b.onclick=()=>navigate(b.dataset.command));}
  const openCommand=()=>{renderCommands();openModal($('#commandPalette'));setTimeout(()=>$('#commandInput').focus(),20)};
