  // ---------- Profile ----------
  function loadProfile(){state.profile=store.get('atlasiq_profile',null);state.evidence=store.get(profileKey('evidence'),[]);state.journal=store.get(profileKey('journal'),[]);updateIdentity();loadCampusState();renderProof();renderJournal();updateNexus();}
  function updateIdentity(){const p=state.profile;const first=p?.name?.split(' ')[0]||'Profile';$('#profileAvatar').textContent=(p?.name||'?').charAt(0).toUpperCase()||'?';$('#profileButtonName').textContent=first;$('#workspaceProfileLabel').textContent=p?`${first}'s local workspace`:'Private local workspace';$('#welcomeLine').textContent=p?`WELCOME, ${first.toUpperCase()}`:'WELCOME TO ATLASIQ';$('#decisionCenterTitle').textContent=p?`${first}'s Decision Center`:'Your Decision Center';$('#campusHeadline').textContent=p?`${first}'s university decisions, modeled before they happen.`:'Your university decisions, modeled before you make them.';$('#campusSubhead').textContent=p?`${p.major||'Student'} at ${p.university||'your university'}. Build plans, test tradeoffs, grow evidence, and keep your personal workspace local.`:'Create a private profile, build a semester, test tradeoffs, identify bottlenecks, and translate your experience into career proof.';if(p?.skills?.length)$('#skillsInput').value=p.skills.join(', ');}
  $('#profileBtn').onclick=()=>{const p=state.profile;$('#profileName').value=p?.name||'';$('#profileUniversity').value=p?.university||'';$('#profileGradYear').value=p?.gradYear||'';$('#profileMajor').value=p?.major||'';$('#profileGoal').value=p?.goal||'';$('#profileSkills').value=(p?.skills||[]).join(', ');openModal($('#profileModal'));};
  $('#profileForm').onsubmit=e=>{e.preventDefault();const existing=state.profile;const p={id:existing?.id||uid('profile'),name:$('#profileName').value.trim(),university:$('#profileUniversity').value.trim(),gradYear:+$('#profileGradYear').value||null,major:$('#profileMajor').value.trim(),goal:$('#profileGoal').value.trim(),skills:splitSkills($('#profileSkills').value),updatedAt:new Date().toISOString()};store.set('atlasiq_profile',p);state.profile=p;closeModal($('#profileModal'));updateIdentity();loadCampusState();renderProof();updateNexus();toast('Private profile saved locally');};
  $('#deleteProfileBtn').onclick=()=>{if(!state.profile)return toast('No saved profile'); if(!confirm('Delete the local AtlasIQ profile and its profile-scoped state from this browser?'))return; const id=state.profile.id;Object.keys(localStorage).filter(k=>k.startsWith(`atlasiq_${id}_`)).forEach(k=>localStorage.removeItem(k));store.del('atlasiq_profile');state.profile=null;state.evidence=[];state.journal=[];loadCampusState();updateIdentity();renderProof();renderJournal();closeModal($('#profileModal'));updateNexus();toast('Local profile deleted');};

  // ---------- Campus tabs ----------
  function activateCampus(tab){$$('.workspace-tab').forEach(b=>b.classList.toggle('active',b.dataset.campusTab===tab));$$('.campus-panel').forEach(p=>p.classList.toggle('active',p.id===`campus-${tab}`));if(tab==='navigator')setTimeout(drawCampusMap,30);}
  $$('.workspace-tab').forEach(b=>b.onclick=()=>activateCampus(b.dataset.campusTab));
  function activateStudio(tab){$$('.studio-tab').forEach(b=>b.classList.toggle('active',b.dataset.studioTab===tab));$$('.studio-panel').forEach(p=>p.classList.toggle('active',p.id===`studio-${tab}`));if(tab==='visuals')setTimeout(()=>{drawMainChart();drawCorrelation();},30);}
  $$('.studio-tab').forEach(b=>b.onclick=()=>activateStudio(b.dataset.studioTab));

  // ---------- Semester Simulator ----------
  const baseCourses=[
    {id:'DATA 101',name:'Foundations of Data Science',credits:3,hours:8,difficulty:3.1,career:8},{id:'STAT 201',name:'Applied Statistics',credits:3,hours:8,difficulty:3.4,career:8},{id:'CS 101',name:'Programming Fundamentals',credits:4,hours:11,difficulty:3.7,career:9},{id:'COMM 110',name:'Professional Communication',credits:3,hours:5,difficulty:2.1,career:6},{id:'MATH 250',name:'Linear Algebra',credits:3,hours:9,difficulty:3.8,career:8},{id:'DATA 310',name:'Machine Learning',credits:3,hours:12,difficulty:4.3,career:10},{id:'ECON 210',name:'Microeconomics',credits:3,hours:7,difficulty:2.9,career:6},{id:'CS 240',name:'Systems Programming',credits:4,hours:13,difficulty:4.2,career:8}
  ];
  let courseCatalog=[];
  function loadCampusState(){courseCatalog=[...baseCourses,...store.get(profileKey('customCourses'),[])];const saved=store.get(profileKey('courses'),[]);state.selectedCourses=saved.map(id=>courseCatalog.find(c=>c.id===id)).filter(Boolean);const prefs=store.get(profileKey('semesterPrefs'),{work:8,club:5,sleep:7.5,commute:25});$('#workHours').value=prefs.work;$('#clubHours').value=prefs.club;$('#sleepHours').value=prefs.sleep;$('#commute').value=prefs.commute;renderCourseSelect();renderCourses();updateSemester();state.career=store.get(profileKey('career'),null);if(state.career)renderCareer(state.career);state.opportunity=store.get(profileKey('opportunity'),null);if(state.opportunity)renderOpportunity(state.opportunity);}
  function renderCourseSelect(){$('#courseSelect').innerHTML=courseCatalog.map((c,i)=>`<option value="${i}">${escapeHTML(c.id)} — ${escapeHTML(c.name)}</option>`).join('');}
  function renderCourses(){$('#selectedCourses').innerHTML=state.selectedCourses.length?state.selectedCourses.map(c=>`<div class="course-chip"><div><b>${escapeHTML(c.id)}</b><small>${escapeHTML(c.name)} · ${c.credits} cr · ${c.hours}h/wk</small></div><button data-remove-course="${escapeHTML(c.id)}">×</button></div>`).join(''):'<p class="microcopy">No courses selected yet.</p>';$$('[data-remove-course]').forEach(b=>b.onclick=()=>{state.selectedCourses=state.selectedCourses.filter(c=>c.id!==b.dataset.removeCourse);persistSemester();renderCourses();updateSemester();});}
  $('#addCourseBtn').onclick=()=>{const c=courseCatalog[+$('#courseSelect').value];if(!c||state.selectedCourses.some(x=>x.id===c.id))return toast('Course already selected');state.selectedCourses.push(c);persistSemester();renderCourses();updateSemester();};
  $('#customCourseBtn').onclick=()=>openModal($('#customCourseModal'));
  $('#customCourseForm').onsubmit=e=>{e.preventDefault();const c={id:$('#customCourseCode').value.trim().toUpperCase(),name:$('#customCourseName').value.trim(),credits:+$('#customCourseCredits').value,hours:+$('#customCourseHours').value,difficulty:+$('#customCourseDifficulty').value,career:+$('#customCourseCareer').value};if(courseCatalog.some(x=>x.id===c.id))return toast('That course code already exists');const custom=store.get(profileKey('customCourses'),[]);custom.push(c);store.set(profileKey('customCourses'),custom);courseCatalog.push(c);state.selectedCourses.push(c);renderCourseSelect();renderCourses();persistSemester();updateSemester();closeModal($('#customCourseModal'));e.target.reset();toast('Custom course added');};
  ['workHours','clubHours','sleepHours','commute'].forEach(id=>$('#'+id).addEventListener('input',()=>{persistSemester();updateSemester();}));
  function persistSemester(){store.set(profileKey('courses'),state.selectedCourses.map(c=>c.id));store.set(profileKey('semesterPrefs'),{work:+$('#workHours').value,club:+$('#clubHours').value,sleep:+$('#sleepHours').value,commute:+$('#commute').value});}
  function updateSemester(){const work=+$('#workHours').value,club=+$('#clubHours').value,sleep=+$('#sleepHours').value,commute=+$('#commute').value;$('#workHoursOut').textContent=work+'h';$('#clubHoursOut').textContent=club+'h';$('#sleepHoursOut').textContent=sleep+'h';$('#commuteOut').textContent=commute+'m';const courseHours=state.selectedCourses.reduce((s,c)=>s+c.hours,0),credits=state.selectedCourses.reduce((s,c)=>s+c.credits,0),difficulty=state.selectedCourses.length?mean(state.selectedCourses.map(c=>c.difficulty)):0,total=courseHours+work+club+(commute*5/60);let score=state.selectedCourses.length?100:58;score-=Math.max(0,total-42)*1.8;score-=Math.max(0,credits-16)*3.5;score-=Math.max(0,difficulty-3.5)*7;score-=Math.max(0,7.5-sleep)*10;score-=Math.max(0,commute-35)*.18;score=round(clamp(score,20,98));const risk=score>=82?'Low':score>=65?'Moderate':'High';state.semester={score,total:round(total,1),credits,difficulty:round(difficulty,1),risk,work,club,sleep,commute,courseHours};store.set(profileKey('semester'),state.semester);$('#semesterScore').textContent=state.selectedCourses.length?score:'—';$('#semesterRing').style.setProperty('--score',state.selectedCourses.length?score:0);$('#semesterVerdict').textContent=!state.selectedCourses.length?'Build a semester':score>=82?'Strong, balanced plan':score>=65?'Ambitious with pressure points':'High-pressure plan';$('#semesterSummary').textContent=!state.selectedCourses.length?'Add courses and adjust commitments.':`Estimated structured load is ${round(total,1)} hours/week with ${credits} credits and ${sleep} hours of sleep per night.`;$('#creditsPill').textContent=`${credits} credits`;$('#loadPill').textContent=`${round(total,1)} hrs/week`;$('#riskPill').textContent=`${risk} risk`;const factors=[['Time capacity',clamp(100-(Math.max(0,total-35)*2),20,100)],['Sleep buffer',clamp((sleep/8)*100,40,100)],['Course difficulty',clamp(105-difficulty*13,30,100)],['Credit load',clamp(105-Math.max(0,credits-12)*5,35,100)]];$('#factorBars').innerHTML=factors.map(([n,v])=>`<div class="factor-bar"><span>${n}</span><i><b style="--w:${round(v)}%"></b></i><em>${round(v)}</em></div>`).join('');$('#semesterExplain').textContent=state.selectedCourses.length?`Balance begins at 100 and applies transparent penalties when modeled commitments exceed a sustainable baseline, when credits/difficulty stack, when sleep falls below 7.5 hours, or when commute becomes unusually high. This is a planning heuristic, not a grade predictor.`:'Add at least one course to activate the model.';$('#metricBalance').textContent=state.selectedCourses.length?score:'—';$('#metricHours').textContent=state.selectedCourses.length?round(total):'—';$('#loadTrend').textContent=state.selectedCourses.length?`${risk} modeled pressure`:'Model a semester';drawWorkload();renderDecisionQueue();updatePulse();updateNexus();renderScenarios();}
  function drawWorkload(){const c=$('#workloadChart'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const base=state.semester?.total||25;const vals=Array.from({length:16},(_,i)=>base*(.78+Math.sin(i*.8)*.08)+(i===7?base*.3:0)+(i===11?base*.22:0));const max=Math.max(...vals,50);ctx.strokeStyle=root.classList.contains('light')?'rgba(20,30,50,.12)':'rgba(255,255,255,.10)';ctx.lineWidth=1;for(let i=1;i<5;i++){ctx.beginPath();ctx.moveTo(40,i*h/5);ctx.lineTo(w-20,i*h/5);ctx.stroke();}ctx.strokeStyle=getComputedStyle(root).getPropertyValue('--gold');ctx.lineWidth=4;ctx.beginPath();vals.forEach((v,i)=>{const x=45+i*(w-75)/(vals.length-1),y=h-35-(v/max)*(h-65);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle=getComputedStyle(root).getPropertyValue('--muted');ctx.font='22px sans-serif';ctx.fillText('Weeks 1–16',40,h-8);$('#workloadInsight').innerHTML=state.selectedCourses.length?`<b>Peak pressure is modeled around weeks 8 and 12.</b> The curve is illustrative: it converts your current weekly load into a semester-shaped planning horizon rather than pretending to know actual exam dates.`:'<b>Model a semester.</b> AtlasIQ will identify the highest-pressure portion of the plan and suggest a tradeoff.';}
  $$('.scenario-save').forEach(b=>b.onclick=()=>{if(!state.selectedCourses.length)return toast('Build a semester first');const scenarios=store.get(profileKey('scenarios'),{});scenarios[b.dataset.slot]={...state.semester,courses:state.selectedCourses.map(c=>c.id),savedAt:new Date().toISOString()};store.set(profileKey('scenarios'),scenarios);renderScenarios();toast(`Scenario ${b.dataset.slot} saved`);});
  function renderScenarios(){const s=store.get(profileKey('scenarios'),{});$('#scenarioCompare').innerHTML=['A','B','C'].map(k=>s[k]?`<div class="scenario-card"><b>${k} · ${s[k].score}/100</b><span>${s[k].credits} credits · ${s[k].total}h/wk</span></div>`:`<div class="scenario-card"><b>${k} · Empty</b><span>Save this plan here</span></div>`).join('');}

  // ---------- Ripple ----------
  $('#rippleMagnitude').oninput=e=>$('#rippleValueLabel').textContent=e.target.value;
  $('#runRipple').onclick=()=>{const type=$('#rippleDecision').value,m=+$('#rippleMagnitude').value,priority=$('#ripplePriority').value,base=state.semester?.score||72;const effects={course:{balance:-5,career:7,time:-7,resilience:-3},job:{balance:-7,career:3,time:-9,resilience:-4},club:{balance:-3,career:5,time:-5,resilience:-2},project:{balance:-4,career:10,time:-6,resilience:1},sleep:{balance:7,career:1,time:-1,resilience:5}}[type];const mult=.7+m*.3,boost=priority==='career'?1.18:priority==='time'?.92:1;const vals={balance:round(clamp(base+effects.balance*mult,0,100)),career:round(clamp((state.career?.score||60)+effects.career*mult*boost,0,100)),time:round(clamp(70+effects.time*mult,0,100)),resilience:round(clamp(78+effects.resilience*mult,0,100))};$('#rippleGraph').innerHTML=`<div class="ripple-center">${escapeHTML($('#rippleDecision').selectedOptions[0].text)}</div><div class="ripple-nodes"><div class="ripple-node"><small>Balance</small><strong>${vals.balance}</strong></div><div class="ripple-node"><small>Career</small><strong>${vals.career}</strong></div><div class="ripple-node"><small>Free time</small><strong>${vals.time}</strong></div><div class="ripple-node"><small>Resilience</small><strong>${vals.resilience}</strong></div></div>`;const direction=effects.career>Math.abs(effects.balance)?'career upside with a meaningful time tradeoff':'a balance-oriented tradeoff';$('#rippleNarrative').textContent=`This counterfactual suggests ${direction}. The displayed point estimates are scenario-comparison aids; a reasonable uncertainty band is roughly ±6–12 points because AtlasIQ does not observe your actual future behavior.`;store.set(profileKey('lastRipple'),{type,m,priority,vals});updateNexus();};

  // ---------- Career ----------
  const roleProfiles={
    'Data Science Intern':['python','sql','statistics','pandas','machine learning','data visualization','communication','git'],
    'Data Analyst Intern':['sql','excel','python','statistics','data visualization','tableau','communication','business analysis'],
    'Machine Learning Intern':['python','machine learning','statistics','linear algebra','pytorch','tensorflow','git','deployment'],
    'Data Engineering Intern':['python','sql','etl','databases','cloud','git','data pipelines','spark'],
    'Software Engineering Intern':['python','java','javascript','git','data structures','algorithms','testing','apis'],
    'Cybersecurity Intern':['networking','linux','python','security','siem','incident response','cloud','communication']
  };
  $('#analyzeSkills').onclick=()=>analyzeCareer();
  function analyzeCareer(){const role=$('#roleSelect').value,have=splitSkills($('#skillsInput').value),need=roleProfiles[role],matched=need.filter(n=>have.some(h=>h.includes(n)||n.includes(h))),missing=need.filter(n=>!matched.includes(n)),evidenceSkills=new Set(state.evidence.map(e=>normalize(e.skill))),verified=matched.filter(m=>[...evidenceSkills].some(e=>e.includes(m)||m.includes(e))),score=round(clamp((matched.length/need.length)*78+(verified.length/need.length)*22,0,100));state.career={role,have,matched,missing,verified,score};store.set(profileKey('career'),state.career);renderCareer(state.career);updatePulse();updateNexus();}
  function renderCareer(c){$('#careerScore').textContent=c.score;$('#careerTitle').textContent=c.score>=80?`Strong foundation for ${c.role}`:c.score>=55?`Competitive base for ${c.role}`:`Build more evidence for ${c.role}`;$('#careerSummary').textContent=`${c.matched.length} of ${roleProfiles[c.role].length} role signals match your current skills; ${c.verified.length} are reinforced by ProofGraph evidence.`;$('#matchedSkills').innerHTML=c.matched.length?c.matched.map(x=>`<span>${escapeHTML(x)}</span>`).join(''):'<span>No matches yet</span>';$('#missingSkills').innerHTML=c.missing.length?c.missing.map(x=>`<span>${escapeHTML(x)}</span>`).join(''):'<span>No major gaps</span>';$('#careerRoadmap').innerHTML=c.missing.slice(0,3).map((x,i)=>`<article><span>SPRINT ${i+1}</span><b>${escapeHTML(x)}</b><small>Build one inspectable artifact or quantified experience showing this skill.</small></article>`).join('');$('#metricCareer').textContent=c.score;$('#careerMini').style.setProperty('--p',c.score);}
  $('#copyResumeBullets').onclick=async()=>{const txt='AtlasIQ — Decision Intelligence Platform\n• Built a privacy-first browser-native decision intelligence system connecting semester simulation, career evidence, public data, and local analytics.\n• Engineered explainable scoring, counterfactual modeling, CSV profiling, lightweight AutoML, what-if analysis, and Atlas Nexus cross-workspace prioritization.\n• Integrated official public-data sources with provenance, local profiles, ProofGraph evidence, Decision Memory, and an on-device assistant.';await navigator.clipboard?.writeText(txt);toast('Project bullets copied');};

