  function profileDataset(){const rows=state.dataset;if(!rows?.length)return null;const cols=Object.keys(rows[0]);const schema=cols.map(c=>{const nums=numericValues(rows,c),missing=rows.filter(r=>String(r[c]??'').trim()==='').length;return {name:c,type:nums.length>=rows.length*.7?'numeric':'categorical',missing,unique:new Set(rows.map(r=>r[c])).size,nums};});const total=rows.length*cols.length,missing=schema.reduce((s,c)=>s+c.missing,0),missingPct=total?missing/total*100:0;let outliers=0;schema.filter(c=>c.type==='numeric').forEach(c=>{const a=[...c.nums].sort((x,y)=>x-y);if(a.length<4)return;const q1=a[Math.floor(a.length*.25)],q3=a[Math.floor(a.length*.75)],iqr=q3-q1,lo=q1-1.5*iqr,hi=q3+1.5*iqr;outliers+=a.filter(v=>v<lo||v>hi).length;});let best={abs:0,r:0,a:'',b:''};const nums=schema.filter(c=>c.type==='numeric');for(let i=0;i<nums.length;i++)for(let j=i+1;j<nums.length;j++){const pairs=rows.map(r=>[Number(r[nums[i].name]),Number(r[nums[j].name])]).filter(p=>p.every(Number.isFinite));const r=correlation(pairs.map(p=>p[0]),pairs.map(p=>p[1]));if(Math.abs(r)>best.abs)best={abs:Math.abs(r),r,a:nums[i].name,b:nums[j].name};}const quality=round(clamp(100-missingPct*1.7-Math.min(20,outliers/Math.max(1,rows.length)*18),0,100));return {rows:rows.length,cols:cols.length,schema,missingPct,outliers,best,quality};}
