  function drawCorrelation(){if(!state.dataset?.length)return;const p=profileDataset(),nums=p.schema.filter(c=>c.type==='numeric').slice(0,7),c=$('#corrCanvas'),ctx=c.getContext('2d'),W=c.width,H=c.height;ctx.clearRect(0,0,W,H);ctx.fillStyle=root.classList.contains('light')?'#ffffff':'#0d1220';ctx.fillRect(0,0,W,H);if(nums.length<2){ctx.fillStyle='#9ca6bc';ctx.font='18px sans-serif';ctx.fillText('Need 2+ numeric columns',30,50);return;}const pad=90,size=Math.min((W-pad-15)/nums.length,(H-pad-15)/nums.length);nums.forEach((a,i)=>nums.forEach((b,j)=>{const pairs=state.dataset.map(r=>[Number(r[a.name]),Number(r[b.name])]).filter(p=>p.every(Number.isFinite)),r=i===j?1:correlation(pairs.map(p=>p[0]),pairs.map(p=>p[1])),alpha=.12+Math.abs(r)*.72;ctx.fillStyle=r>=0?`rgba(245,207,98,${alpha})`:`rgba(102,229,255,${alpha})`;ctx.fillRect(pad+i*size,20+j*size,size-2,size-2);ctx.fillStyle='#111';ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillText(round(r,2),pad+i*size+size/2,20+j*size+size/2+4);}));ctx.fillStyle=root.classList.contains('light')?'#222a3c':'#dfe5f1';ctx.font='12px sans-serif';ctx.textAlign='right';nums.forEach((n,i)=>ctx.fillText(n.name.slice(0,10),pad-6,20+i*size+size/2+4));}

