  function trainLinear(train,features,target){const f=features[0];const pairs=train.map(r=>[Number(r[f]),Number(r[target])]).filter(p=>p.every(Number.isFinite));if(pairs.length<3)return null;const xs=pairs.map(p=>p[0]),ys=pairs.map(p=>p[1]),mx=mean(xs),my=mean(ys);let num=0,den=0;xs.forEach((x,i)=>{num+=(x-mx)*(ys[i]-my);den+=(x-mx)**2});const b=den?num/den:0,a=my-b*mx;return {name:`Linear · ${f}`,predict:r=>a+b*Number(r[f]),feature:f};}
  function knnPredict(train,features,target,row,k=3){const scored=train.map(r=>{let d=0,n=0;features.forEach(f=>{const a=Number(r[f]),b=Number(row[f]);if(Number.isFinite(a)&&Number.isFinite(b)){d+=(a-b)**2;n++;}});return {r,d:n?Math.sqrt(d/n):Infinity};}).sort((a,b)=>a.d-b.d).slice(0,k);return mean(scored.map(x=>Number(x.r[target])).filter(Number.isFinite));}
  function accuracy(y,p){return y.length?y.filter((v,i)=>String(v)===String(p[i])).length/y.length:0;}
  $('#runAutoML').onclick=()=>{if(!state.dataset?.length)return toast('Load a dataset first');const p=profileDataset(),target=$('#targetColumn').value,tSchema=p.schema.find(c=>c.name===target),features=p.schema.filter(c=>c.name!==target&&c.type==='numeric').map(c=>c.name).slice(0,6);if(!tSchema)return;const rows=state.dataset.filter(r=>String(r[target]??'')!=='');const cut=Math.max(1,Math.floor(rows.length*.8)),train=rows.slice(0,cut),test=rows.slice(cut);if(test.length<1)return toast('Dataset is too small for a holdout');let models=[];if(tSchema.type==='numeric'){const y=test.map(r=>Number(r[target])).filter(Number.isFinite);const baseline=mean(train.map(r=>Number(r[target])).filter(Number.isFinite)),rmse=(pred)=>Math.sqrt(mean(y.map((v,i)=>(v-pred[i])**2)));models.push({name:'Mean baseline',score:rmse(y.map(()=>baseline)),metric:'RMSE'});const lin=trainLinear(train,features,target);if(lin){const pred=test.map(lin.predict);models.push({name:lin.name,score:rmse(pred),metric:'RMSE',feature:lin.feature});}if(features.length){const pred=test.map(r=>knnPredict(train,features,target,r,3));models.push({name:'k-NN regression',score:rmse(pred),metric:'RMSE'});}models=models.filter(m=>Number.isFinite(m.score)).sort((a,b)=>a.score-b.score);}else{const labels=train.map(r=>r[target]),counts={};labels.forEach(v=>counts[v]=(counts[v]||0)+1);const maj=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0],truth=test.map(r=>r[target]);models.push({name:'Majority baseline',score:accuracy(truth,test.map(()=>maj)),metric:'Accuracy'});if(features.length){const pred=test.map(row=>{const near=train.map(r=>{let d=0,n=0;features.forEach(f=>{const a=Number(r[f]),b=Number(row[f]);if(Number.isFinite(a)&&Number.isFinite(b)){d+=(a-b)**2;n++;}});return {label:r[target],d:n?Math.sqrt(d/n):Infinity};}).sort((a,b)=>a.d-b.d).slice(0,3);const c={};near.forEach(x=>c[x.label]=(c[x.label]||0)+1);return Object.entries(c).sort((a,b)=>b[1]-a[1])[0]?.[0];});models.push({name:'k-NN classifier',score:accuracy(truth,pred),metric:'Accuracy'});}models.sort((a,b)=>b.score-a.score);}const winner=models[0];state.automl={target,type:tSchema.type,models,winner,features};$('#modelEmpty').classList.add('hidden');$('#modelResults').classList.remove('hidden');$('#winningModel').textContent=winner?.name||'No valid model';$('#winningScore').textContent=winner?(winner.metric==='RMSE'?round(winner.score,3):round(winner.score*100,1)+'%'):'—';$('#winningMetric').textContent=winner?.metric||'score';$('#winningExplanation').textContent=tSchema.type==='numeric'?'Lower holdout RMSE is better. This lightweight arena is useful for comparison, not production validation.':'Higher holdout accuracy is better. Small datasets can make this estimate unstable.';$('#modelGrid').innerHTML=models.map((m,i)=>`<article class="model-card ${i===0?'winner':''}"><small>${i===0?'WINNER':'MODEL'}</small><b>${escapeHTML(m.name)}</b><strong>${m.metric==='RMSE'?round(m.score,3):round(m.score*100,1)+'%'}</strong><small>${m.metric}</small></article>`).join('');const influences=features.map(f=>{const pairs=state.dataset.map(r=>[Number(r[f]),Number(r[target])]).filter(p=>p.every(Number.isFinite));return [f,Math.abs(correlation(pairs.map(p=>p[0]),pairs.map(p=>p[1])))*100]}).sort((a,b)=>b[1]-a[1]);$('#featureImportance').innerHTML=influences.map(([n,v])=>`<div class="factor-bar"><span>${escapeHTML(n)}</span><i><b style="--w:${round(v)}%"></b></i><em>${round(v)}</em></div>`).join('')||'<p class="microcopy">No numeric influence proxy available.</p>';$('#modelWhy').textContent=`AtlasIQ compared ${models.length} lightweight browser-native approaches using a deterministic 80/20 holdout. Feature influence shown here is an absolute Pearson association proxy, not causal importance.`;updateNexus();};

  // ---------- Studio simulation + local analyst ----------
  $('#simAdjustment').oninput=e=>$('#simAdjustmentOut').textContent=(+e.target.value>=0?'+':'')+e.target.value+'%';
  $('#runDataSimulation').onclick=()=>{if(!state.dataset?.length)return toast('Load a dataset first');const target=$('#simTarget').value,feature=$('#simFeature').value,adj=+$('#simAdjustment').value/100,targetVals=numericValues(state.dataset,target),featureVals=numericValues(state.dataset,feature);if(!targetVals.length||!featureVals.length)return toast('Choose numeric target and driver');const pairs=state.dataset.map(r=>[Number(r[feature]),Number(r[target])]).filter(p=>p.every(Number.isFinite)),r=correlation(pairs.map(p=>p[0]),pairs.map(p=>p[1])),base=mean(targetVals),sim=base*(1+r*adj);$('#baselineOutcome').textContent=round(base,2);$('#simulatedOutcome').textContent=round(sim,2);$('#simulationNarrative').innerHTML=`<p><b>Association-based what-if:</b> a ${round(adj*100)}% change in ${escapeHTML(feature)} is translated through its observed correlation with ${escapeHTML(target)} (r=${round(r,2)}). This is sensitivity analysis, not a causal prediction.</p>`;drawSimulation(base,sim);};
  function drawSimulation(base,sim){const c=$('#simulationChart'),ctx=c.getContext('2d'),W=c.width,H=c.height;ctx.clearRect(0,0,W,H);ctx.fillStyle=root.classList.contains('light')?'#fff':'#0d1220';ctx.fillRect(0,0,W,H);const m=Math.max(Math.abs(base),Math.abs(sim),1);[['BASELINE',base,'#f5cf62'],['SIMULATED',sim,'#66e5ff']].forEach((x,i)=>{const bh=Math.abs(x[1])/m*(H-110);ctx.fillStyle=x[2];ctx.fillRect(180+i*350,H-55-bh,180,bh);ctx.fillStyle=root.classList.contains('light')?'#1b2438':'#eaf0fb';ctx.font='22px sans-serif';ctx.textAlign='center';ctx.fillText(x[0],270+i*350,H-18);});}
  $('#chatForm').onsubmit=e=>{e.preventDefault();const q=$('#chatInput').value.trim();if(!q)return;addDatasetMessage(q,'user');$('#chatInput').value='';setTimeout(()=>addDatasetMessage(answerDataset(q),'ai'),120);};$$('#studio-explain .suggestion-chips button').forEach(b=>b.onclick=()=>{addDatasetMessage(b.textContent,'user');setTimeout(()=>addDatasetMessage(answerDataset(b.textContent),'ai'),100);});
  function addDatasetMessage(t,type){const d=document.createElement('div');d.className=`message ${type}`;d.textContent=t;$('#chatMessages').appendChild(d);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;}
  function answerDataset(q){if(!state.dataset?.length)return'Load a CSV or public dataset first. I can then explain quality, relationships, modeling, and preprocessing using only local state.';const p=profileDataset(),s=normalize(q);if(s.includes('stand out'))return`The clearest signals are a ${p.quality}/100 quality score, ${round(p.missingPct,1)}% missingness, ${p.outliers} IQR outlier flags${p.best.a?`, and the strongest numeric relationship ${p.best.a} ↔ ${p.best.b} at r=${round(p.best.r,2)}`:''}.`;if(s.includes('matter')||s.includes('variable'))return p.best.a?`${p.best.a} and ${p.best.b} have the strongest observed numeric association. Treat that as a screening signal, not proof of importance or causality.`:'There are not enough numeric pairs for a reliable relationship screen.';if(s.includes('preprocess'))return`Start by reviewing ${round(p.missingPct,1)}% missingness, validating inferred types, inspecting ${p.outliers} IQR outlier flags, and separating identifiers from predictive features.`;if(s.includes('model'))return state.automl?`${state.automl.winner.name} currently wins the lightweight holdout comparison for ${state.automl.target}. Check Methodology before treating it as more than a prototype result.`:'Run AutoML first so I can explain the winning holdout result.';return`I’m using the active local dataset: ${state.datasetName}, ${p.rows} rows, ${p.cols} columns, quality ${p.quality}/100. Ask about missingness, correlations, outliers, preprocessing, or the AutoML result.`;}

  // ---------- Data Vault (IndexedDB) ----------
  const DB='AtlasIQVaultV2',STORE='datasets';
  const openDB=()=>new Promise((res,rej)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE,{keyPath:'id'});};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});
  async function saveVault(){if(!state.dataset?.length)return toast('Load a dataset first');try{const db=await openDB(),tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put({id:uid('data'),profileId:state.profile?.id||'guest',name:state.datasetName,rows:state.dataset.slice(0,2000),savedAt:new Date().toISOString()});await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});toast('Dataset saved locally');}catch{toast('Local vault unavailable in this browser');}}
  async function listVault(){try{const db=await openDB(),tx=db.transaction(STORE,'readonly'),req=tx.objectStore(STORE).getAll();const all=await new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)}),mine=all.filter(x=>x.profileId===(state.profile?.id||'guest'));$('#vaultList').innerHTML=mine.length?mine.map(x=>`<div class="vault-item"><div><b>${escapeHTML(x.name)}</b><small>${x.rows.length} rows · ${new Date(x.savedAt).toLocaleString()}</small></div><div class="inline-actions"><button class="button tiny" data-open-vault="${x.id}">Open</button><button class="button tiny danger" data-delete-vault="${x.id}">Delete</button></div></div>`).join(''):'<div class="empty-state compact"><h4>No saved datasets</h4><p>Save an active Studio dataset to keep a local copy.</p></div>';$$('[data-open-vault]').forEach(b=>b.onclick=()=>{const x=mine.find(d=>d.id===b.dataset.openVault);if(x){loadDataset(x.rows,x.name);closeModal($('#vaultModal'));}});$$('[data-delete-vault]').forEach(b=>b.onclick=async()=>{const db2=await openDB(),tx2=db2.transaction(STORE,'readwrite');tx2.objectStore(STORE).delete(b.dataset.deleteVault);tx2.oncomplete=()=>listVault();});}catch{$('#vaultList').innerHTML='<p>IndexedDB is unavailable in this browser context.</p>';}}
  $('#saveDataset').onclick=saveVault;$('#vaultBtn').onclick=()=>{openModal($('#vaultModal'));listVault();};
  $('#exportReport').onclick=()=>{if(!state.dataset)return toast('Load a dataset first');const p=profileDataset();downloadText('atlasiq-analysis-report.json',JSON.stringify({generatedAt:new Date().toISOString(),dataset:state.datasetName,profile:p,automl:state.automl,methodology:'Browser-native exploratory analysis; not production validation.'},null,2),'application/json');};

  // ---------- Public Data Observatory ----------
  const publicFallback={
    worldbank:{value:'340M+',meta:'Cached illustrative U.S. population magnitude. Live World Bank retrieval unavailable.',rows:parseCSV('year,population\n2019,328329953\n2020,331577720\n2021,332099760\n2022,334017321\n2023,336806231')},
    usgs:{value:'Live feed',meta:'Cached mode: open the USGS source for current event counts.',rows:parseCSV('magnitude,depth_km,longitude,latitude\n3.2,10,-117.4,35.7\n2.8,8,-122.1,38.1\n4.1,15,-155.3,19.5\n2.6,6,-116.8,33.9')},
    bls:{value:'Index',meta:'Cached example mode. Live BLS retrieval unavailable.',rows:parseCSV('period,value\nM01,308.4\nM02,310.3\nM03,312.2\nM04,313.5\nM05,314.1')}
  };
  async function loadPublicData(){let live=0;$('#publicStatus').textContent='Refreshing official public sources…';
    try{const r=await fetch('https://api.worldbank.org/v2/country/USA/indicator/SP.POP.TOTL?format=json&per_page=12');const j=await r.json(),obs=(j[1]||[]).filter(x=>x.value!=null);if(!obs.length)throw 0;const latest=obs[0],rows=obs.slice(0,10).reverse().map(x=>({year:x.date,population:String(x.value)}));state.publicData.worldbank={rows,value:new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(latest.value),meta:`Latest available observation: ${latest.date}. Indicator SP.POP.TOTL.`,live:true};live++;}catch{state.publicData.worldbank={...publicFallback.worldbank,live:false};}
    try{const r=await fetch('https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_week.geojson');const j=await r.json(),features=j.features||[];state.publicData.usgs={rows:features.slice(0,300).map(f=>({time:new Date(f.properties.time).toISOString(),magnitude:String(f.properties.mag??''),depth_km:String(f.geometry.coordinates[2]??''),longitude:String(f.geometry.coordinates[0]),latitude:String(f.geometry.coordinates[1]),place:f.properties.place||''})),value:String(features.length),meta:`USGS M2.5+ past-7-days GeoJSON feed · generated ${new Date(j.metadata.generated).toLocaleString()}.`,live:true};live++;}catch{state.publicData.usgs={...publicFallback.usgs,live:false};}
    try{const r=await fetch('https://api.bls.gov/publicAPI/v1/timeseries/data/CUUR0000SA0');const j=await r.json(),series=j.Results?.series?.[0]?.data||[];if(!series.length)throw 0;state.publicData.bls={rows:series.slice(0,36).reverse().map(x=>({year:x.year,period:x.period,period_name:x.periodName,value:x.value})),value:series[0].value,meta:`CPI-U All Items · ${series[0].periodName} ${series[0].year}. BLS series CUUR0000SA0.`,live:true};live++;}catch{state.publicData.bls={...publicFallback.bls,live:false};}
    renderPublic();$('#publicStatus').textContent=`${live}/3 sources live · ${3-live} transparent fallback${3-live===1?'':'s'}`;updateNexus();}
  function renderPublic(){for(const key of ['worldbank','usgs','bls']){const d=state.publicData[key],prefix=key==='worldbank'?'wb':key;$('#'+prefix+'Value').textContent=d.value;$('#'+prefix+'Meta').textContent=d.meta;$('#'+prefix+'Freshness').textContent=d.live?'LIVE':'CACHED EXAMPLE';}}
  $('#refreshPublic').onclick=loadPublicData;$$('.public-to-studio').forEach(b=>b.onclick=()=>{const d=state.publicData[b.dataset.source];if(!d?.rows)return toast('Public source is not ready yet');loadDataset(d.rows,`${b.dataset.source}_${d.live?'live':'cached'}.csv`);toast(`${b.dataset.source} data opened in Studio`);});

  // ---------- Atlas Pulse + Nexus ----------
  function updatePulse(){const signals=[];if(state.semester?.score)signals.push(state.semester.score);if(state.career?.score)signals.push(state.career.score);signals.push(clamp(35+state.evidence.length*9,0,100));signals.push(clamp(40+state.journal.length*8+state.journal.filter(j=>j.outcome!=null).length*8,0,100));const pulse=round(mean(signals));$('#metricPulse').textContent=pulse||'—';store.set(profileKey('pulse'),pulse);}
  function nexusInputs(){const p=profileDataset(),reviewed=state.journal.filter(j=>j.outcome!=null),cal=reviewed.length?mean(reviewed.map(j=>100-Math.abs(j.confidence-j.outcome))):null;return [
    {name:'Semester balance',value:state.selectedCourses.length?state.semester?.score:null,weight:.22,target:'campus:semester'},
    {name:'Career readiness',value:state.career?.score??null,weight:.22,target:'campus:career'},
    {name:'Proof coverage',value:state.evidence.length?clamp(35+state.evidence.length*10,0,100):null,weight:.16,target:'proofgraph'},
    {name:'Opportunity fit',value:state.opportunity?.score??null,weight:.14,target:'campus:opportunity'},
    {name:'Decision calibration',value:cal,weight:.10,target:'campus:journal'},
    {name:'Data quality',value:p?.quality??null,weight:.10,target:'studio:data'},
    {name:'Public-data activity',value:Object.values(state.publicData).length?clamp(45+Object.values(state.publicData).filter(x=>x.live).length*15+(state.datasetName.includes('worldbank')||state.datasetName.includes('usgs')||state.datasetName.includes('bls')?10:0),0,100):null,weight:.06,target:'public-data'}
  ];}
  function updateNexus(){const inp=nexusInputs(),available=inp.filter(x=>Number.isFinite(x.value)),weight=available.reduce((s,x)=>s+x.weight,0),raw=weight?available.reduce((s,x)=>s+x.value*x.weight,0)/weight:0,completeness=inp.length?available.length/inp.length:0,score=available.length?round(raw*(.78+.22*completeness)):null;$('#nexusScore').textContent=score??'—';$('#heroNexusScore').textContent=score??'—';$('#nexusRing').style.setProperty('--score',score||0);$('#nexusLabel').textContent=score==null?'Build your workspace to activate Nexus.':`${available.length}/${inp.length} signal groups active · completeness ${round(completeness*100)}%`;$('#nexusFactors').innerHTML=inp.map(x=>`<div class="factor-row"><span>${escapeHTML(x.name)}</span><i><b style="--w:${x.value==null?0:round(x.value)}%"></b></i><em>${x.value==null?'—':round(x.value)}</em></div>`).join('');let action=inp.filter(x=>x.value==null).sort((a,b)=>b.weight-a.weight)[0]||available.sort((a,b)=>a.value-b.value)[0];if(action){$('#nexusActionTitle').textContent=action.value==null?`Activate ${action.name}`:`Strengthen ${action.name}`;$('#nexusActionText').textContent=action.value==null?`This high-weight signal is missing from Nexus. Use the linked workflow to improve coverage and confidence.`:`At ${round(action.value)}/100, this is currently your weakest active signal. Improving it should have the largest direct effect on the connected score.`;$('#nexusActionBtn').onclick=()=>navigate(action.target);}store.set(profileKey('nexus'),{score,inputs:inp,updatedAt:new Date().toISOString()});}
  $('#refreshNexus').onclick=()=>{updateNexus();toast('Nexus recomputed from current workspace');};
