  $('#amyFab').onclick=()=>{$('#amyPanel').classList.add('open');$('#amyPanel').setAttribute('aria-hidden','false')};$('#amyClose').onclick=()=>{$('#amyPanel').classList.remove('open');$('#amyPanel').setAttribute('aria-hidden','true')};
  $('#amyForm').onsubmit=e=>{e.preventDefault();const q=$('#amyInput').value.trim();if(!q)return;amyMsg(q,'user');$('#amyInput').value='';setTimeout(()=>amyMsg(answerAmy(q),'ai'),100);};$$('#amyPanel .suggestion-chips button').forEach(b=>b.onclick=()=>{amyMsg(b.textContent,'user');setTimeout(()=>amyMsg(answerAmy(b.textContent),'ai'),80)});
