  function answerAmy(q){const n=store.get(profileKey('nexus'),{}),s=normalize(q);if(s.includes('next')){const inp=n.inputs||nexusInputs(),a=inp.filter(x=>x.value==null).sort((a,b)=>b.weight-a.weight)[0]||inp.filter(x=>x.value!=null).sort((a,b)=>a.value-b.value)[0];return a?`${a.value==null?'Activate':'Strengthen'} ${a.name}. That is currently the clearest high-leverage gap in your connected workspace.`:'Start with a local profile and Semester Simulator so Nexus has meaningful signals.';}if(s.includes('nexus'))return n.score==null?'Your Nexus score is not active yet. Use Campus, ProofGraph, or Studio first.':`Your Nexus score is ${n.score}/100. It is based only on active signals; missing modules lower completeness instead of being treated as perfect.`;if(s.includes('start'))return'Create your local profile, model a semester, run Career Intelligence, add one ProofGraph item, then analyze either a CSV or one Public Data Observatory series. Nexus will connect those signals.';if(s.includes('privacy'))return'Your profile, evidence, decisions, and uploaded datasets are processed locally. Public Data Observatory makes read-only requests to official public sources.';return'I can explain Nexus, suggest your next step, describe privacy, or navigate you toward Campus, Studio, ProofGraph, Public Data, or Methodology.';}

